-- Mathematically integral JSON numbers have one exact source tuple identity.
-- Direct private-helper rows below are synthetic and transaction-local, not Auth acceptance.
begin;
select plan(28);
select is(concierge.review_source_location_canonical('{"sourceId":"ABCDEF00-0000-4000-8000-000000000001","sourceVersion":1.0,"locator":{"kind":"whole"}}'),'{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"whole"}}'::jsonb,'scaled version canonicalizes without a text-to-bigint cast');
select is(concierge.review_source_location_canonical('{"sourceId":"ABCDEF00-0000-4000-8000-000000000001","sourceVersion":1.00,"locator":{"kind":"text","start":0.0,"end":1.0}}'),'{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"text","start":0,"end":1}}'::jsonb,'scaled text offsets retain exact validated values');
select is(concierge.review_source_location_canonical('{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1e0,"locator":{"kind":"time","startMs":-0.0,"endMs":1e3}}'),'{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"time","startMs":0,"endMs":1000}}'::jsonb,'negative zero and integral exponent retain time range');
select is(concierge.review_source_location_canonical('{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"page","page":1.00}}'),'{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"page","page":1}}'::jsonb,'scaled positive page canonicalizes');
select is(concierge.review_source_location_canonical('{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":9007199254740991.0,"locator":{"kind":"page","page":9007199254740991.0}}')->>'sourceVersion','9007199254740991','maximum safe integer remains exact');
select is((select count(distinct concierge.review_source_location_canonical(v))::integer from jsonb_array_elements('[{"sourceId":"ABCDEF00-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"text","start":0,"end":1}},{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1.0,"locator":{"kind":"text","start":0.00,"end":1.00}}]') v),1,'equivalent exact tuples deduplicate regardless of numeric scale');
select throws_ok($$select concierge.review_source_location_canonical('{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1.5,"locator":{"kind":"whole"}}')$$,'P0001','concierge_invalid_input','fractional version rejects rather than rounds');
select throws_ok($$select concierge.review_source_location_canonical('{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"text","start":0,"end":1.5}}')$$,'P0001','concierge_invalid_input','fractional offset rejects rather than rounds');
select throws_ok($$select concierge.review_source_location_canonical('{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":9007199254740992,"locator":{"kind":"whole"}}')$$,'P0001','concierge_invalid_input','unsafe version rejects');
select throws_ok($$select concierge.review_source_location_canonical('{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"time","startMs":0,"endMs":9007199254740992}}')$$,'P0001','concierge_invalid_input','unsafe time bound rejects');
select throws_ok($$select concierge.review_source_location_canonical('{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":-1,"locator":{"kind":"whole"}}')$$,'P0001','concierge_invalid_input','negative source version rejects');
select throws_ok($$select concierge.review_source_location_canonical('{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"text","start":-1,"end":1}}')$$,'P0001','concierge_invalid_input','negative offset rejects');
select throws_ok($$select concierge.review_source_location_canonical('{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"page","page":0.0}}')$$,'P0001','concierge_invalid_input','page zero remains invalid');
select throws_ok($$select concierge.review_source_location_canonical('{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"time","startMs":8.0,"endMs":4.0}}')$$,'P0001','concierge_invalid_input','reversed scaled range remains invalid');
select throws_ok($$select concierge.review_source_location_canonical('{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"text","start":4.0,"end":4.00}}')$$,'P0001','concierge_invalid_input','equal scaled range remains invalid');
select throws_ok($$select concierge.review_source_location_canonical('{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"whole","extra":1}}')$$,'P0001','concierge_invalid_input','canonicalization cannot discard unknown locator fields');
select is((select count(*)::integer from pg_proc p where p.oid in ('concierge.review_source_location_canonical(jsonb)'::regprocedure,'concierge.review_source_check(uuid,jsonb,uuid)'::regprocedure) and (p.prosecdef or not coalesce(p.proconfig @> array['search_path=""'],false) or has_function_privilege('anon',p.oid,'execute') or has_function_privilege('authenticated',p.oid,'execute') or has_function_privilege('service_role',p.oid,'execute'))),0,'helpers stay private invokers with empty search paths');

insert into auth.users(id,email,is_anonymous) values
 ('bbbbbb00-0000-4000-8000-000000000001','locator-advisor@example.invalid',false),
 ('bbbbbb00-0000-4000-8000-000000000002','locator-client@example.invalid',false),
 ('bbbbbb00-0000-4000-8000-000000000003','locator-other-client@example.invalid',false);
insert into public.profiles(id) values('bbbbbb00-0000-4000-8000-000000000001') on conflict(id) do nothing;
insert into concierge.advisors(user_id,active,can_view,can_edit) values('bbbbbb00-0000-4000-8000-000000000001',true,true,true);
insert into concierge.plan_principals(actor_id,kind) values('bbbbbb00-0000-4000-8000-000000000001','human');
insert into concierge.cases(client_id) values('bbbbbb00-0000-4000-8000-000000000002'),('bbbbbb00-0000-4000-8000-000000000003');
insert into concierge.plan_sources(id,client_id,version) values('abcdef00-0000-4000-8000-000000000001','bbbbbb00-0000-4000-8000-000000000002',1),('abcdef00-0000-4000-8000-000000000002','bbbbbb00-0000-4000-8000-000000000003',1);
insert into concierge.plan_source_permissions(actor_id,source_id) values('bbbbbb00-0000-4000-8000-000000000001','abcdef00-0000-4000-8000-000000000001');
select lives_ok($$select concierge.review_source_check('bbbbbb00-0000-4000-8000-000000000002','[{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1.0,"locator":{"kind":"whole"}}]','bbbbbb00-0000-4000-8000-000000000001')$$,'live scoped source accepts scaled version');
select lives_ok($$select concierge.review_source_check('bbbbbb00-0000-4000-8000-000000000002','[{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1.0,"locator":{"kind":"text","start":0.0,"end":1.0}}]','bbbbbb00-0000-4000-8000-000000000001')$$,'live scoped source accepts scaled text bounds');
select lives_ok($$select concierge.review_source_check('bbbbbb00-0000-4000-8000-000000000002','[{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1.0,"locator":{"kind":"time","startMs":0.0,"endMs":1e3}}]','bbbbbb00-0000-4000-8000-000000000001')$$,'live scoped source accepts scaled time bounds');
select lives_ok($$select concierge.review_source_check('bbbbbb00-0000-4000-8000-000000000002','[{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1.0,"locator":{"kind":"page","page":1.0}}]','bbbbbb00-0000-4000-8000-000000000001')$$,'live scoped source accepts scaled page');
select throws_ok($$select concierge.review_source_check('bbbbbb00-0000-4000-8000-000000000002','[{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"whole"}},{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"text","start":8,"end":4}}]','bbbbbb00-0000-4000-8000-000000000001')$$,'P0001','concierge_invalid_input','every raw tuple validates before source permission deduplication');
select throws_ok($$select concierge.review_source_check('bbbbbb00-0000-4000-8000-000000000002','[{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":2.0,"locator":{"kind":"whole"}}]','bbbbbb00-0000-4000-8000-000000000001')$$,'P0001','concierge_source_conflict','scaled changed source version still conflicts');
select throws_ok($$select concierge.review_source_check('bbbbbb00-0000-4000-8000-000000000002','[{"sourceId":"abcdef00-0000-4000-8000-000000000002","sourceVersion":1.0,"locator":{"kind":"whole"}}]','bbbbbb00-0000-4000-8000-000000000001')$$,'P0001','concierge_source_conflict','another client source remains out of scope');
select throws_ok($$select concierge.review_source_check('bbbbbb00-0000-4000-8000-000000000002','[{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1.0,"locator":{"kind":"whole"}}]','bbbbbb00-0000-4000-8000-000000000003')$$,'P0001','concierge_forbidden','non-advisor caller remains denied');
delete from concierge.plan_source_permissions where actor_id='bbbbbb00-0000-4000-8000-000000000001';
select throws_ok($$select concierge.review_source_check('bbbbbb00-0000-4000-8000-000000000002','[{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1.0,"locator":{"kind":"whole"}}]','bbbbbb00-0000-4000-8000-000000000001')$$,'P0001','concierge_forbidden','revoked exact source permission remains denied');
insert into concierge.plan_source_permissions(actor_id,source_id) values('bbbbbb00-0000-4000-8000-000000000001','abcdef00-0000-4000-8000-000000000001');
update concierge.plan_sources set active=false where id='abcdef00-0000-4000-8000-000000000001';
select throws_ok($$select concierge.review_source_check('bbbbbb00-0000-4000-8000-000000000002','[{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1.0,"locator":{"kind":"whole"}}]','bbbbbb00-0000-4000-8000-000000000001')$$,'P0001','concierge_source_conflict','deleted source cannot regain authority through numeric normalization');
update concierge.plan_sources set active=true where id='abcdef00-0000-4000-8000-000000000001';
update concierge.advisors set active=false where user_id='bbbbbb00-0000-4000-8000-000000000001';
select throws_ok($$select concierge.review_source_check('bbbbbb00-0000-4000-8000-000000000002','[{"sourceId":"abcdef00-0000-4000-8000-000000000001","sourceVersion":1.0,"locator":{"kind":"whole"}}]','bbbbbb00-0000-4000-8000-000000000001')$$,'P0001','concierge_forbidden','revoked advisor cannot use retained source grant');
select * from finish();
rollback;
